html:
{%- macro readings_table(qi) -%}
<table class="coc-readings">
	<thead><tr><th>Parameter</th><th style="width:22%">Specification</th><th style="width:9%" class="num">Min</th>
		<th style="width:9%" class="num">Max</th><th style="width:18%">Observed</th><th style="width:9%">Result</th></tr></thead>
	<tbody>
	{%- for r in qi.readings -%}
	<tr>
		<td>{{ r.specification }}</td>
		<td>{{ r.value or (r.acceptance_formula if r.formula_based_criteria else "") or "&mdash;" }}</td>
		<td class="num">{{ r.get_formatted("min_value") if r.min_value is not none else "&mdash;" }}</td>
		<td class="num">{{ r.get_formatted("max_value") if r.max_value is not none else "&mdash;" }}</td>
		<td>{%- if r.numeric -%}
			{{ [r.reading_1, r.reading_2, r.reading_3, r.reading_4, r.reading_5] | select("ne", none) | join(" / ") or "&mdash;" }}
			{%- else -%}{{ r.reading_value or "&mdash;" }}{%- endif -%}</td>
		<td>{% if r.status == "Accepted" %}<span class="coc-ok">Accepted</span>{% else %}{{ r.status }}{% endif %}</td>
	</tr>
	{%- endfor -%}
	</tbody>
</table>
{%- endmacro -%}


<style>
	.print-format { font-family: "Helvetica Neue", Arial, sans-serif; font-size: 9.5pt; color: #111; }
	.coc-band { border-bottom: 2pt solid #1f3d2b; padding-bottom: 6pt; margin-bottom: 10pt;
		display: flex; justify-content: space-between; align-items: flex-end; }
	.coc-co { font-size: 13pt; font-weight: 800; color: #1f3d2b; letter-spacing: 0.3pt; }
	.coc-title { font-size: 15pt; font-weight: 800; letter-spacing: 1.5pt; text-align: right; }
	.coc-meta { width: 100%; border-collapse: collapse; margin-bottom: 10pt; }
	.coc-meta td { border: 0.6pt solid #000; padding: 3.5pt 6pt; font-size: 8.5pt; vertical-align: top; }
	.coc-lbl { font-size: 6.2pt; text-transform: uppercase; letter-spacing: 0.5pt; color: #555;
		font-weight: 700; display: block; margin-bottom: 1pt; }
	table.coc-items, table.coc-readings { width: 100%; border-collapse: collapse; margin: 4pt 0 10pt; }
	.coc-items th, .coc-items td, .coc-readings th, .coc-readings td {
		border: 0.5pt solid #666; padding: 3pt 4.5pt; font-size: 8pt; text-align: left; vertical-align: top; }
	.coc-items th, .coc-readings th { background: #f2f2f2; font-size: 6.8pt; text-transform: uppercase;
		letter-spacing: 0.3pt; }
	.coc-h { font-size: 9pt; font-weight: 700; margin: 8pt 0 2pt; color: #1f3d2b; }
	.coc-stage { font-size: 7.6pt; font-weight: 700; margin: 5pt 0 1pt; text-transform: uppercase;
		letter-spacing: 0.4pt; color: #444; }
	.coc-sub { font-size: 7.5pt; color: #555; }
	.coc-ok { color: #1f5d3f; font-weight: 700; }
	.coc-statement { border: 0.8pt solid #1f3d2b; background: #f4f6f4; padding: 6pt 8pt;
		font-size: 8.6pt; margin: 12pt 0 14pt; }
	.coc-sign { width: 100%; margin-top: 18pt; }
	.coc-sign td { width: 50%; font-size: 8pt; vertical-align: bottom; padding-top: 24pt; }
	.coc-sig-line { border-top: 0.6pt solid #000; padding-top: 2pt; width: 70%; }
	.coc-foot { margin-top: 14pt; border-top: 0.5pt solid #999; padding-top: 3pt; font-size: 6.4pt;
		color: #666; display: flex; justify-content: space-between; }
	.num { text-align: right; }
</style>

<div class="coc-band">
	<div>
		<div class="coc-co">{{ doc.company }}</div>
		<div class="coc-sub">Quality Management System &middot; ISO 9001:2015</div>
	</div>
	<div class="coc-title">CERTIFICATE OF CONFORMITY</div>
</div>

<table class="coc-meta"><tr>
	<td style="width:34%"><span class="coc-lbl">Customer</span>
		<strong>{{ doc.customer_name or doc.customer }}</strong>
		{% if doc.address_display %}<div class="coc-sub">{{ doc.address_display }}</div>{% endif %}</td>
	<td style="width:22%"><span class="coc-lbl">Certificate / Delivery Note No.</span><strong>{{ doc.name }}</strong>
		<div class="coc-sub">Date: {{ doc.get_formatted("posting_date") }}</div></td>
	<td style="width:22%"><span class="coc-lbl">Customer PO</span>{{ doc.po_no or "&mdash;" }}
		{% if doc.po_date %}<div class="coc-sub">dated {{ doc.get_formatted("po_date") }}</div>{% endif %}</td>
	<td style="width:22%"><span class="coc-lbl">Vehicle / LR</span>{{ doc.lr_no or "&mdash;" }}
		{% if doc.lr_date %}<div class="coc-sub">dated {{ doc.get_formatted("lr_date") }}</div>{% endif %}</td>
</tr></table>

<table class="coc-items">
	<thead><tr><th style="width:4%">#</th><th style="width:16%">Item Code</th><th>Description</th>
		<th style="width:13%">Batch</th><th style="width:9%" class="num">Qty</th>
		<th style="width:14%">Inspection Ref.</th><th style="width:9%">Result</th></tr></thead>
	<tbody>
	{%- for row in doc.items -%}
	{%- set qi = frappe.get_doc("Quality Inspection", row.quality_inspection) if row.quality_inspection else None -%}
	<tr>
		<td>{{ loop.index }}</td>
		<td>{{ row.item_code }}</td>
		<td>{{ row.item_name }}</td>
		<td>{{ row.batch_no or "&mdash;" }}</td>
		<td class="num">{{ row.get_formatted("qty") }} {{ row.uom }}</td>
		<td>{{ row.quality_inspection or "&mdash;" }}</td>
		<td>{% if qi %}<span class="coc-ok">{{ qi.status }}</span>{% else %}&mdash;{% endif %}</td>
	</tr>
	{%- endfor -%}
	</tbody>
</table>

{%- for row in doc.items -%}
{%- set chain = coc_row_inspections(row) -%}
{%- if chain.outgoing or chain.pdi or chain.in_process -%}
<div class="coc-h">Inspection Evidence &mdash; {{ row.item_code }}{% if row.batch_no %} <span class="coc-sub">Batch {{ row.batch_no }}</span>{% endif %}{% if chain.work_orders %} <span class="coc-sub">&middot; Work Order {{ chain.work_orders | join(", ") }}</span>{% endif %}</div>

{%- if chain.outgoing -%}
<div class="coc-stage">Despatch Inspection &mdash; {{ chain.outgoing.name }}{% if chain.outgoing.report_date %} &middot; {{ chain.outgoing.get_formatted("report_date") }}{% endif %} &middot; <span class="coc-ok">{{ chain.outgoing.status }}</span></div>
{{ readings_table(chain.outgoing) }}
{%- endif -%}

{%- for qi in chain.pdi -%}
<div class="coc-stage">Final Inspection (PDI) &mdash; {{ qi.name }}{% if qi.report_date %} &middot; {{ qi.get_formatted("report_date") }}{% endif %} &middot; <span class="coc-ok">{{ qi.status }}</span></div>
{{ readings_table(qi) }}
{%- endfor -%}

{%- if chain.in_process -%}
<div class="coc-stage">In-Process Inspections during Production &mdash; {{ chain.in_process | length }} performed</div>
{%- for qi in chain.in_process -%}
<div class="coc-sub" style="margin: 3pt 0 1pt">{{ qi.name }}{% if qi.report_date %} &middot; {{ qi.get_formatted("report_date") }}{% endif %} &middot; {{ qi.status }}</div>
{{ readings_table(qi) }}
{%- endfor -%}
{%- endif -%}
{%- endif -%}
{%- endfor -%}

<div class="coc-statement">
	We hereby certify that the goods listed above have been manufactured, inspected and tested in
	accordance with the applicable specifications and customer requirements, and were found to
	<strong>conform</strong> at the time of despatch.
</div>

<table class="coc-sign"><tr>
	<td><div class="coc-sig-line">Inspected / Verified By</div></td>
	<td><div class="coc-sig-line">For {{ doc.company }} &mdash; Authorised Signatory</div></td>
</tr></table>

<div class="coc-foot">
	<span>HCCPL/QMS/FRM-030 &middot; Issue 01 / Rev 00 &middot; Certificate of Conformity</span>
	<span>Generated from ERPNext &middot; {{ frappe.utils.now_datetime().strftime("%d-%m-%Y %H:%M") }}</span>
</div>
